"""SQLAlchemy models for the Cat-egory database.

Conventions
-----------
* Primary keys are ``BIGINT GENERATED BY DEFAULT AS IDENTITY`` (cheap, sortable, keyset-pagination friendly).
  Scan jobs use UUIDs because their IDs travel through the queue and appear in logs and URLs.
* Enumerations are ``VARCHAR + CHECK`` (``native_enum=False``) so adding a value is a cheap migration.
* Timestamps are ``timestamptz`` in UTC.
* Category assignments are temporal rows: the current state has ``valid_to IS NULL``.
"""
from __future__ import annotations

import enum
import uuid
from datetime import datetime
from decimal import Decimal

from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    DateTime,
    Enum,
    ForeignKey,
    Identity,
    Index,
    Integer,
    MetaData,
    Numeric,
    SmallInteger,
    String,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import ARRAY, INET, JSONB, UUID
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, relationship

NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)


# --------------------------------------------------------------------------- enums


class StrEnum(enum.StrEnum):
    def __str__(self) -> str:  # pragma: no cover - cosmetic
        return self.value


class CategoryKind(StrEnum):
    CONTENT = "content"  # what the site is about
    RISK = "risk"  # security threat classification, kept apart from content


class ClassificationStatus(StrEnum):
    UNCLASSIFIED = "unclassified"  # never analysed
    PENDING = "pending"  # analysed, awaiting extra validation
    CLASSIFIED = "classified"  # accepted automatically by policy (not human-verified)
    NEEDS_REVIEW = "needs_review"  # waiting for a human
    VERIFIED = "verified"  # confirmed by a human / calibrated agreement rule
    DISPUTED = "disputed"  # open community report against the current classification
    REANALYZE = "reanalyze"  # low confidence, queued for another analysis
    UNREACHABLE = "unreachable"  # DNS/HTTP failure, nothing to classify


class AssignmentOrigin(StrEnum):
    AI = "ai"
    HUMAN = "human"
    COMMUNITY = "community"
    SOURCE = "source"  # imported from a third-party list
    RULE = "rule"  # follows from a registry's allocation policy (e.g. only public bodies get .gov.tr)


class ScanReason(StrEnum):
    MANUAL = "manual"
    IMPORT = "import"
    SCHEDULED = "scheduled"
    COMMUNITY = "community"
    RESCAN = "rescan"
    DISCOVERY = "discovery"  # first scan of a domain found through a discovery source (daily budget)


class JobStatus(StrEnum):
    QUEUED = "queued"
    RUNNING = "running"
    SUCCEEDED = "succeeded"
    FAILED = "failed"
    BLOCKED = "blocked"  # refused by SSRF / robots.txt / policy
    CANCELLED = "cancelled"


class Visibility(StrEnum):
    PRIVATE = "private"  # admins/moderators only
    PUBLIC = "public"  # publishing permission verified


class ValidationStatus(StrEnum):
    VALID = "valid"
    INVALID_JSON = "invalid_json"
    INVALID_SCHEMA = "invalid_schema"
    INVALID_CATEGORY = "invalid_category"
    PROVIDER_ERROR = "provider_error"


class EvidenceType(StrEnum):
    HTML = "html"
    TEXT = "text"
    SCREENSHOT = "screenshot"
    METADATA = "metadata"
    REDIRECT = "redirect"
    SOURCE = "source"
    HUMAN = "human"
    SYSTEM = "system"  # e.g. "prompt-injection phrase detected"


class ThreatType(StrEnum):
    MALWARE = "malware"
    PHISHING = "phishing"
    SCAM = "scam"
    FRAUD = "fraud"
    COMMAND_AND_CONTROL = "command-and-control"
    MALICIOUS_DOWNLOADS = "malicious-downloads"
    SUSPICIOUS = "suspicious"
    LOOKALIKE_DOMAIN = "lookalike-domain"


class SourceKind(StrEnum):
    MANUAL = "manual"
    FILE_IMPORT = "file_import"
    COMMUNITY = "community"
    BLOCKLIST = "blocklist"
    THREAT_FEED = "threat_feed"
    DATASET = "dataset"
    AI = "ai"
    RULE = "rule"


class SubmissionType(StrEnum):
    NEW_DOMAIN = "new_domain"
    CATEGORY_CORRECTION = "category_correction"
    FALSE_POSITIVE = "false_positive"
    FALSE_NEGATIVE = "false_negative"
    VERIFICATION = "verification"


class ModerationStatus(StrEnum):
    PENDING = "pending"
    ACCEPTED = "accepted"
    REJECTED = "rejected"
    SPAM = "spam"


class ReviewStatus(StrEnum):
    OPEN = "open"
    IN_PROGRESS = "in_progress"
    DONE = "done"
    SKIPPED = "skipped"


class Role(StrEnum):
    ADMIN = "admin"
    MODERATOR = "moderator"
    CONTRIBUTOR = "contributor"


def _enum(e: type[enum.Enum], name: str) -> Enum:
    return Enum(
        e,
        name=name,
        native_enum=False,
        create_constraint=True,
        length=32,
        values_callable=lambda cls: [m.value for m in cls],
        validate_strings=True,
    )


def _now() -> Mapped[datetime]:
    return mapped_column(DateTime(timezone=True), server_default=func.now(), nullable=False)


def _pk() -> Mapped[int]:
    return mapped_column(BigInteger, Identity(always=False), primary_key=True)


CONFIDENCE = Numeric(4, 3)


def _confidence_check(column: str) -> CheckConstraint:
    return CheckConstraint(f"{column} IS NULL OR ({column} >= 0 AND {column} <= 1)", name=f"{column}_range")


# --------------------------------------------------------------------------- accounts


class User(Base):
    __tablename__ = "users"

    id: Mapped[int] = _pk()
    email: Mapped[str] = mapped_column(String(320), unique=True, nullable=False)
    display_name: Mapped[str] = mapped_column(String(100), nullable=False)
    role: Mapped[Role] = mapped_column(_enum(Role, "role"), nullable=False, default=Role.CONTRIBUTOR)
    password_hash: Mapped[str | None] = mapped_column(Text)  # Argon2id; NULL = API-key-only account
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    created_at: Mapped[datetime] = _now()
    last_login_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    __table_args__ = (CheckConstraint("email = lower(email)", name="email_lowercase"),)


class ApiKey(Base):
    """API keys are shown once; only a prefix (for lookup) and a SHA-256 hash are stored."""

    __tablename__ = "api_keys"

    id: Mapped[int] = _pk()
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), nullable=False, index=True)
    name: Mapped[str] = mapped_column(String(100), nullable=False)
    prefix: Mapped[str] = mapped_column(String(16), unique=True, nullable=False)
    key_hash: Mapped[str] = mapped_column(String(64), nullable=False)
    scopes: Mapped[list[str]] = mapped_column(ARRAY(String(32)), nullable=False, server_default=text("'{}'"))
    rate_limit_per_minute: Mapped[int | None] = mapped_column(Integer)
    created_at: Mapped[datetime] = _now()
    last_used_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    expires_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    revoked_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))


# --------------------------------------------------------------------------- sources & licences


class SourceLicense(Base):
    __tablename__ = "source_licenses"

    id: Mapped[int] = _pk()
    slug: Mapped[str] = mapped_column(String(64), unique=True, nullable=False)  # SPDX id where one exists
    name: Mapped[str] = mapped_column(String(200), nullable=False)
    url: Mapped[str | None] = mapped_column(Text)
    redistribution_allowed: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    commercial_use_allowed: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    attribution_required: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    share_alike: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    notes: Mapped[str | None] = mapped_column(Text)
    reviewed_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    reviewed_by_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))


class DataSource(Base):
    __tablename__ = "data_sources"

    id: Mapped[int] = _pk()
    slug: Mapped[str] = mapped_column(String(64), unique=True, nullable=False)
    name: Mapped[str] = mapped_column(String(200), nullable=False)
    kind: Mapped[SourceKind] = mapped_column(_enum(SourceKind, "source_kind"), nullable=False)
    homepage_url: Mapped[str | None] = mapped_column(Text)
    feed_url: Mapped[str | None] = mapped_column(Text)
    data_format: Mapped[str | None] = mapped_column(String(32))  # hosts, domains, csv, json, ...
    terms_url: Mapped[str | None] = mapped_column(Text)
    attribution: Mapped[str | None] = mapped_column(Text)
    license_id: Mapped[int | None] = mapped_column(ForeignKey("source_licenses.id", ondelete="RESTRICT"))
    update_interval_seconds: Mapped[int | None] = mapped_column(Integer)
    enabled: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    last_sync_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    last_success_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    last_error: Mapped[str | None] = mapped_column(Text)
    quality_score: Mapped[Decimal | None] = mapped_column(CONFIDENCE)
    record_count: Mapped[int] = mapped_column(BigInteger, nullable=False, server_default=text("0"))
    created_at: Mapped[datetime] = _now()

    license: Mapped[SourceLicense | None] = relationship()

    __table_args__ = (_confidence_check("quality_score"),)


# --------------------------------------------------------------------------- taxonomy


class TaxonomyVersion(Base):
    __tablename__ = "taxonomy_versions"

    id: Mapped[int] = _pk()
    version: Mapped[str] = mapped_column(String(32), unique=True, nullable=False)  # semver, e.g. "1.0.0"
    released_at: Mapped[datetime] = _now()
    notes: Mapped[str | None] = mapped_column(Text)
    is_current: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))

    __table_args__ = (
        Index("uq_taxonomy_versions_single_current", "is_current", unique=True, postgresql_where=text("is_current")),
    )


class Category(Base):
    """A taxonomy node. ``id`` (slug) and ``code`` are stable forever and never reused."""

    __tablename__ = "categories"

    id: Mapped[str] = mapped_column(String(64), primary_key=True)
    code: Mapped[int] = mapped_column(SmallInteger, unique=True, nullable=False)
    parent_id: Mapped[str | None] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"), index=True)
    kind: Mapped[CategoryKind] = mapped_column(_enum(CategoryKind, "category_kind"), nullable=False)
    name: Mapped[str] = mapped_column(String(100), nullable=False)
    description: Mapped[str] = mapped_column(Text, nullable=False)
    is_group: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    introduced_in: Mapped[str] = mapped_column(String(32), nullable=False)
    deprecated_in: Mapped[str | None] = mapped_column(String(32))
    replaced_by_id: Mapped[str | None] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"))

    parent: Mapped[Category | None] = relationship(remote_side=[id], foreign_keys=[parent_id])


# --------------------------------------------------------------------------- domains & urls


class Domain(Base):
    __tablename__ = "domains"

    id: Mapped[int] = _pk()
    domain: Mapped[str] = mapped_column(String(253), nullable=False)  # display form (may be Unicode)
    normalized_domain: Mapped[str] = mapped_column(String(253), unique=True, nullable=False)  # ASCII/punycode
    registrable_domain: Mapped[str] = mapped_column(String(253), nullable=False, index=True)
    public_suffix: Mapped[str] = mapped_column(String(100), nullable=False)

    # denormalised current classification (source of truth: domain_categories with valid_to IS NULL)
    primary_category_id: Mapped[str | None] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"), index=True)
    secondary_categories: Mapped[list[str]] = mapped_column(ARRAY(String(64)), nullable=False, server_default=text("'{}'"))
    confidence: Mapped[Decimal | None] = mapped_column(CONFIDENCE)
    classification_status: Mapped[ClassificationStatus] = mapped_column(
        _enum(ClassificationStatus, "classification_status"), nullable=False, default=ClassificationStatus.UNCLASSIFIED,
        index=True,
    )

    first_seen: Mapped[datetime] = _now()
    last_seen: Mapped[datetime] = _now()
    last_scanned: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    next_scan: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    scan_count: Mapped[int] = mapped_column(Integer, nullable=False, server_default=text("0"))
    source_id: Mapped[int | None] = mapped_column(ForeignKey("data_sources.id", ondelete="SET NULL"))  # first source
    source_license: Mapped[str | None] = mapped_column(String(64))  # licence slug of the first source
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    created_at: Mapped[datetime] = _now()
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False
    )

    __table_args__ = (
        _confidence_check("confidence"),
        CheckConstraint("normalized_domain = lower(normalized_domain)", name="normalized_lowercase"),
        Index("ix_domains_next_scan_active", "next_scan", postgresql_where=text("is_active")),
    )


class DomainSourceRecord(Base):
    """Provenance: which sources reported a domain (one row per domain × source), merged on import."""

    __tablename__ = "domain_source_records"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    source_id: Mapped[int] = mapped_column(ForeignKey("data_sources.id", ondelete="CASCADE"), nullable=False, index=True)
    source_category: Mapped[str | None] = mapped_column(String(200))  # the label the source used
    # Position in the source's list after its filters (1 = first). Discovery scans popular domains first.
    source_rank: Mapped[int | None] = mapped_column(Integer)
    first_seen: Mapped[datetime] = _now()
    last_seen: Mapped[datetime] = _now()
    is_listed: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))

    __table_args__ = (UniqueConstraint("domain_id", "source_id"),
                      Index("ix_domain_source_records_source_rank", "source_id", "source_rank"))


class Url(Base):
    __tablename__ = "urls"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False, index=True)
    url: Mapped[str] = mapped_column(Text, nullable=False)
    normalized_url: Mapped[str] = mapped_column(Text, nullable=False)
    url_hash: Mapped[str] = mapped_column(String(64), unique=True, nullable=False)  # sha256(normalized_url)
    first_seen: Mapped[datetime] = _now()
    last_seen: Mapped[datetime] = _now()
    last_scanned: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    created_at: Mapped[datetime] = _now()


# --------------------------------------------------------------------------- scanning


class ScanJob(Base):
    __tablename__ = "scan_jobs"

    id: Mapped[uuid.UUID] = mapped_column(UUID(as_uuid=True), primary_key=True, default=uuid.uuid4)
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False, index=True)
    url_id: Mapped[int | None] = mapped_column(ForeignKey("urls.id", ondelete="SET NULL"))
    requested_by_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    reason: Mapped[ScanReason] = mapped_column(_enum(ScanReason, "scan_reason"), nullable=False)
    priority: Mapped[int] = mapped_column(SmallInteger, nullable=False, server_default=text("5"))
    status: Mapped[JobStatus] = mapped_column(_enum(JobStatus, "job_status"), nullable=False, default=JobStatus.QUEUED)
    attempts: Mapped[int] = mapped_column(SmallInteger, nullable=False, server_default=text("0"))
    max_attempts: Mapped[int] = mapped_column(SmallInteger, nullable=False, server_default=text("3"))
    task_id: Mapped[str | None] = mapped_column(String(64))
    error_code: Mapped[str | None] = mapped_column(String(64))
    error_detail: Mapped[str | None] = mapped_column(Text)
    queued_at: Mapped[datetime] = _now()
    started_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))
    finished_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    __table_args__ = (
        CheckConstraint("priority BETWEEN 0 AND 9", name="priority_range"),
        Index("ix_scan_jobs_open", "status", "priority", "queued_at",
              postgresql_where=text("status IN ('queued', 'running')")),
        # at most one open job per domain, enforced even under concurrent inserts
        Index("uq_scan_jobs_one_open_per_domain", "domain_id", unique=True,
              postgresql_where=text("status IN ('queued', 'running')")),
        Index("ix_scan_jobs_queued_at_id", "queued_at", "id"),
    )


class ScanResult(Base):
    __tablename__ = "scan_results"

    id: Mapped[int] = _pk()
    scan_job_id: Mapped[uuid.UUID] = mapped_column(ForeignKey("scan_jobs.id", ondelete="CASCADE"), nullable=False, unique=True)
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    requested_url: Mapped[str] = mapped_column(Text, nullable=False)
    final_url: Mapped[str | None] = mapped_column(Text)
    http_status: Mapped[int | None] = mapped_column(SmallInteger)
    redirect_chain: Mapped[list] = mapped_column(JSONB, nullable=False, server_default=text("'[]'::jsonb"))
    resolved_ips: Mapped[list[str]] = mapped_column(ARRAY(INET), nullable=False, server_default=text("'{}'"))
    dns: Mapped[dict] = mapped_column(JSONB, nullable=False, server_default=text("'{}'::jsonb"))
    tls: Mapped[dict | None] = mapped_column(JSONB)
    response_headers: Mapped[dict] = mapped_column(JSONB, nullable=False, server_default=text("'{}'::jsonb"))
    content_type: Mapped[str | None] = mapped_column(String(200))
    content_length: Mapped[int | None] = mapped_column(Integer)
    page_title: Mapped[str | None] = mapped_column(Text)
    meta_description: Mapped[str | None] = mapped_column(Text)
    open_graph: Mapped[dict] = mapped_column(JSONB, nullable=False, server_default=text("'{}'::jsonb"))
    language_hint: Mapped[str | None] = mapped_column(String(16))
    robots_allowed: Mapped[bool | None] = mapped_column(Boolean)
    blocked_reason: Mapped[str | None] = mapped_column(String(64))
    timings: Mapped[dict] = mapped_column(JSONB, nullable=False, server_default=text("'{}'::jsonb"))
    created_at: Mapped[datetime] = _now()

    __table_args__ = (Index("ix_scan_results_domain_created", "domain_id", "created_at"),)


class Screenshot(Base):
    __tablename__ = "screenshots"

    id: Mapped[int] = _pk()
    scan_result_id: Mapped[int] = mapped_column(ForeignKey("scan_results.id", ondelete="CASCADE"), nullable=False, index=True)
    object_key: Mapped[str] = mapped_column(Text, nullable=False)
    sha256: Mapped[str] = mapped_column(String(64), nullable=False)
    mime_type: Mapped[str] = mapped_column(String(50), nullable=False)
    width: Mapped[int] = mapped_column(Integer, nullable=False)
    height: Mapped[int] = mapped_column(Integer, nullable=False)
    size_bytes: Mapped[int] = mapped_column(Integer, nullable=False)
    visibility: Mapped[Visibility] = mapped_column(_enum(Visibility, "visibility"), nullable=False, default=Visibility.PRIVATE)
    retention_until: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), index=True)
    created_at: Mapped[datetime] = _now()


class ExtractedContent(Base):
    __tablename__ = "extracted_content"

    id: Mapped[int] = _pk()
    scan_result_id: Mapped[int] = mapped_column(ForeignKey("scan_results.id", ondelete="CASCADE"), nullable=False, unique=True)
    html_object_key: Mapped[str | None] = mapped_column(Text)
    html_sha256: Mapped[str | None] = mapped_column(String(64))
    html_size_bytes: Mapped[int | None] = mapped_column(Integer)
    text_object_key: Mapped[str | None] = mapped_column(Text)
    text_excerpt: Mapped[str | None] = mapped_column(Text)  # bounded excerpt used for AI input and search
    word_count: Mapped[int | None] = mapped_column(Integer)
    link_count: Mapped[int | None] = mapped_column(Integer)
    visibility: Mapped[Visibility] = mapped_column(_enum(Visibility, "visibility"), nullable=False, default=Visibility.PRIVATE)
    retention_until: Mapped[datetime | None] = mapped_column(DateTime(timezone=True), index=True)
    created_at: Mapped[datetime] = _now()


# --------------------------------------------------------------------------- AI & classification


class AIPrediction(Base):
    """What a model claimed. Never published directly; feeds and the API read domain_categories."""

    __tablename__ = "ai_predictions"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    scan_result_id: Mapped[int | None] = mapped_column(ForeignKey("scan_results.id", ondelete="SET NULL"), index=True)
    provider: Mapped[str] = mapped_column(String(32), nullable=False)
    model: Mapped[str] = mapped_column(String(100), nullable=False)
    prompt_version: Mapped[str] = mapped_column(String(32), nullable=False)
    taxonomy_version: Mapped[str] = mapped_column(String(32), nullable=False)
    validation_status: Mapped[ValidationStatus] = mapped_column(_enum(ValidationStatus, "validation_status"), nullable=False)
    validation_errors: Mapped[list] = mapped_column(JSONB, nullable=False, server_default=text("'[]'::jsonb"))
    primary_category_id: Mapped[str | None] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"))
    secondary_category_ids: Mapped[list[str]] = mapped_column(ARRAY(String(64)), nullable=False, server_default=text("'{}'"))
    risk_flags: Mapped[list[str]] = mapped_column(ARRAY(String(64)), nullable=False, server_default=text("'{}'"))
    confidence: Mapped[Decimal | None] = mapped_column(CONFIDENCE)
    language: Mapped[str | None] = mapped_column(String(16))
    site_type: Mapped[str | None] = mapped_column(String(32))
    description: Mapped[str | None] = mapped_column(Text)  # model claim, never shown as fact
    requires_human_review: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    used_screenshot: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    raw_response: Mapped[dict | None] = mapped_column(JSONB)
    input_tokens: Mapped[int | None] = mapped_column(Integer)
    output_tokens: Mapped[int | None] = mapped_column(Integer)
    latency_ms: Mapped[int | None] = mapped_column(Integer)
    request_id: Mapped[str | None] = mapped_column(String(100))
    created_at: Mapped[datetime] = _now()

    __table_args__ = (
        _confidence_check("confidence"),
        Index("ix_ai_predictions_domain_created", "domain_id", "created_at"),
    )


class DomainCategory(Base):
    """Temporal category assignment. Current rows: ``valid_to IS NULL``; the rest is history."""

    __tablename__ = "domain_categories"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    category_id: Mapped[str] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"), nullable=False, index=True)
    is_primary: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    confidence: Mapped[Decimal | None] = mapped_column(CONFIDENCE)
    origin: Mapped[AssignmentOrigin] = mapped_column(_enum(AssignmentOrigin, "assignment_origin"), nullable=False)
    source_id: Mapped[int | None] = mapped_column(ForeignKey("data_sources.id", ondelete="RESTRICT"))
    ai_prediction_id: Mapped[int | None] = mapped_column(ForeignKey("ai_predictions.id", ondelete="SET NULL"))
    assigned_by_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    taxonomy_version: Mapped[str] = mapped_column(String(32), nullable=False)
    valid_from: Mapped[datetime] = _now()
    valid_to: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    __table_args__ = (
        _confidence_check("confidence"),
        CheckConstraint("valid_to IS NULL OR valid_to >= valid_from", name="valid_period"),
        Index("uq_domain_categories_current", "domain_id", "category_id", unique=True,
              postgresql_where=text("valid_to IS NULL")),
        Index("uq_domain_categories_one_primary", "domain_id", unique=True,
              postgresql_where=text("valid_to IS NULL AND is_primary")),
        Index("ix_domain_categories_history", "domain_id", "valid_from"),
    )


