class Evidence(Base):
    """An observation supporting a prediction or a submission. ``verified`` is set by humans only."""

    __tablename__ = "evidence"

    id: Mapped[int] = _pk()
    ai_prediction_id: Mapped[int | None] = mapped_column(ForeignKey("ai_predictions.id", ondelete="CASCADE"), index=True)
    community_submission_id: Mapped[int | None] = mapped_column(
        ForeignKey("community_submissions.id", ondelete="CASCADE"), index=True
    )
    type: Mapped[EvidenceType] = mapped_column(_enum(EvidenceType, "evidence_type"), nullable=False)
    observation: Mapped[str] = mapped_column(Text, nullable=False)
    reference: Mapped[str | None] = mapped_column(Text)  # object key / URL / source reference
    verified: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    created_at: Mapped[datetime] = _now()

    __table_args__ = (
        CheckConstraint("num_nonnulls(ai_prediction_id, community_submission_id) = 1", name="single_owner"),
    )


class ReviewTask(Base):
    __tablename__ = "review_tasks"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    ai_prediction_id: Mapped[int | None] = mapped_column(ForeignKey("ai_predictions.id", ondelete="SET NULL"))
    reason: Mapped[str] = mapped_column(String(64), nullable=False)  # low_confidence, conflict, injection, report, ...
    status: Mapped[ReviewStatus] = mapped_column(_enum(ReviewStatus, "review_status"), nullable=False, default=ReviewStatus.OPEN)
    assigned_to_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    decided_by_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    decision_primary_id: Mapped[str | None] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"))
    decision_secondary_ids: Mapped[list[str]] = mapped_column(ARRAY(String(64)), nullable=False, server_default=text("'{}'"))
    decision_note: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _now()
    decided_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    __table_args__ = (Index("ix_review_tasks_open", "status", "created_at", postgresql_where=text("status = 'open'")),)


class ThreatIntelligence(Base):
    """Threat reports from verified sources. Kept apart from AI predictions on purpose."""

    __tablename__ = "threat_intelligence"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False)
    url_id: Mapped[int | None] = mapped_column(ForeignKey("urls.id", ondelete="CASCADE"))
    threat_type: Mapped[ThreatType] = mapped_column(_enum(ThreatType, "threat_type"), nullable=False)
    source_id: Mapped[int] = mapped_column(ForeignKey("data_sources.id", ondelete="RESTRICT"), nullable=False)
    source_reference: Mapped[str | None] = mapped_column(Text)  # the source's own ID / URL for the report
    confidence: Mapped[Decimal | None] = mapped_column(CONFIDENCE)
    first_seen: Mapped[datetime] = _now()
    last_seen: Mapped[datetime] = _now()
    is_active: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("true"))
    raw: Mapped[dict | None] = mapped_column(JSONB)

    __table_args__ = (
        _confidence_check("confidence"),
        Index("ix_threat_intelligence_domain_active", "domain_id", postgresql_where=text("is_active")),
        Index("uq_threat_intelligence_report", "domain_id", "threat_type", "source_id",
              text("coalesce(url_id, 0)"), unique=True),
    )


# --------------------------------------------------------------------------- community


class CommunitySubmission(Base):
    __tablename__ = "community_submissions"

    id: Mapped[int] = _pk()
    type: Mapped[SubmissionType] = mapped_column(_enum(SubmissionType, "submission_type"), nullable=False)
    domain_id: Mapped[int | None] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), index=True)
    submitted_domain: Mapped[str] = mapped_column(String(253), nullable=False)  # normalised input
    proposed_category_ids: Mapped[list[str]] = mapped_column(ARRAY(String(64)), nullable=False, server_default=text("'{}'"))
    comment: Mapped[str | None] = mapped_column(Text)
    submitter_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    submitter_fingerprint: Mapped[str | None] = mapped_column(String(64))  # keyed hash of IP; raw IPs are not stored
    status: Mapped[ModerationStatus] = mapped_column(
        _enum(ModerationStatus, "moderation_status"), nullable=False, default=ModerationStatus.PENDING
    )
    moderator_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    moderation_note: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _now()
    resolved_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))

    __table_args__ = (Index("ix_community_submissions_pending", "created_at", postgresql_where=text("status = 'pending'")),)


class CommunityVote(Base):
    __tablename__ = "community_votes"

    id: Mapped[int] = _pk()
    submission_id: Mapped[int] = mapped_column(ForeignKey("community_submissions.id", ondelete="CASCADE"), nullable=False)
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"), nullable=False)
    vote: Mapped[int] = mapped_column(SmallInteger, nullable=False)
    created_at: Mapped[datetime] = _now()

    __table_args__ = (
        UniqueConstraint("submission_id", "user_id"),
        CheckConstraint("vote IN (-1, 1)", name="vote_value"),
    )


class FalsePositiveReport(Base):
    """Structured report that a category (or threat flag) on a domain is wrong or missing."""

    __tablename__ = "false_positive_reports"

    id: Mapped[int] = _pk()
    domain_id: Mapped[int] = mapped_column(ForeignKey("domains.id", ondelete="CASCADE"), nullable=False, index=True)
    category_id: Mapped[str] = mapped_column(ForeignKey("categories.id", ondelete="RESTRICT"), nullable=False)
    is_false_negative: Mapped[bool] = mapped_column(Boolean, nullable=False, server_default=text("false"))
    community_submission_id: Mapped[int | None] = mapped_column(ForeignKey("community_submissions.id", ondelete="SET NULL"))
    reporter_id: Mapped[int | None] = mapped_column(ForeignKey("users.id", ondelete="SET NULL"))
    reporter_fingerprint: Mapped[str | None] = mapped_column(String(64))
    reason: Mapped[str] = mapped_column(Text, nullable=False)
    status: Mapped[ModerationStatus] = mapped_column(
        _enum(ModerationStatus, "moderation_status"), nullable=False, default=ModerationStatus.PENDING
    )
    resolution: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[datetime] = _now()
    resolved_at: Mapped[datetime | None] = mapped_column(DateTime(timezone=True))


